UPDATE courses SET
    course_description = '<h4>Course Intro</h4><div> <div> <p>This is a qualification suitable for individuals who are seeking a career in working on light vehicles in the automotive retail, service and repair industry. And those who are keen to enter a new industry sector.</p> </div> </div><h4>Course Outline</h4><div> <div> <div> <table> <tbody> <tr> <th colspan="2">Core Unit</th> </tr> <tr> <td width="97">AURAEA002</td> <td width="468">Follow environmental and sustainability best practice in an automotive workplace</td> </tr> <tr> <td>AURASA102</td> <td>Follow safe working practices in an automotive workplace</td> </tr> <tr> <td>AURETK002</td> <td>Use and maintain electrical test equipment in an automotive workplace</td> </tr> <tr> <td>AURETR006</td> <td>Solder electrical wiring and circuits</td> </tr> <tr> <td>AURETR007</td> <td>Apply knowledge of automotive electrical circuits and wiring systems</td> </tr> <tr> <td>AURETR027</td> <td>Install ancillary electronic systems and components</td> </tr> <tr> <td>AURETR010</td> <td>Repair wiring harnesses and looms</td> </tr> <tr> <td>AURETR135</td> <td>Apply knowledge of petrol and diesel engine operation</td> </tr> <tr> <td>AURETR112</td> <td>Test and repair basic electrical circuits</td> </tr> <tr> <td>AURETR123</td> <td>Diagnose and repair spark ignition engine management systems</td> </tr> <tr> <td>AURETR125</td> <td>Test, charge and replace batteries and jump-start vehicles</td> </tr> <tr> <td>AURETR128</td> <td>Diagnose and repair instruments and warning systems</td> </tr> <tr> <td>AURETR129</td> <td>Diagnose and repair charging systems</td> </tr> <tr> <td>AURETR130</td> <td>Diagnose and repair starting systems</td> </tr> <tr> <td>AURETR131</td> <td>Diagnose and repair ignition systems</td> </tr> <tr> <td>AURETR132</td> <td>Diagnose and repair automotive electrical systems</td> </tr> <tr> <td>AURTTE104</td> <td>Inspect and service engines</td> </tr> <tr> <td>AURTTA118</td> <td>Develop and carry out diagnostic test strategies</td> </tr> <tr> <td>AURETR009</td> <td>Install vehicle lighting and wiring systems</td> </tr> <tr> <td>AURETR124</td> <td>Diagnose and repair compression ignition engine management systems</td> </tr> <tr> <td>AURETR143</td> <td>Diagnose and repair electronic body management systems</td> </tr> </tbody> </table> </div> </div> <div> <div> <table> <tbody> <tr> <th colspan="2">Elective Unit</th> </tr> <tr> <td width="97">AURTTK102</td> <td width="468">Use and maintain tools and equipment in an automotive workplace</td> </tr> <tr> <td>AURAFA103</td> <td>Communicate effectively in an automotive workplace</td> </tr> <tr> <td>AURTTB101</td> <td>Inspect and service braking systems</td> </tr> <tr> <td>AURLTB103</td> <td>Diagnose and repair light vehicle hydraulic braking systems</td> </tr> <tr> <td>AURLTD104</td> <td>Diagnose and repair light vehicle steering systems</td> </tr> <tr> <td>AURLTD105</td> <td>Diagnose and repair light vehicle suspension systems</td> </tr> <tr> <td>AURTTA105</td> <td>Select and use bearings, seals, gaskets, sealants and adhesives</td> </tr> <tr> <td>AURTTC103</td> <td>Diagnose and repair cooling systems</td> </tr> <tr> <td>AURTTF101</td> <td>Inspect and service petrol fuel systems</td> </tr> <tr> <td>AURLTE102</td> <td>Diagnose and repair light vehicle engines</td> </tr> <tr> <td>AURTTA104</td> <td>Carry out servicing operations</td> </tr> </tbody> </table> </div> </div> </div><h4>Learning Outcomes &amp; Career Pathways</h4><div><h3>QUALIFICATION</h3> <div> <div> <p>On successful completion of this course the student would be awarded AUR30320 Certificate III in Automotive Electrical Technology which is nationally recognised qualification. This could help student gain entry into relevant career paths. Students who do not complete all units and/or works placement may be eligible for a Statement of Attainment in partial completion of a AUR30320 Certificate III in Automotive Electrical Technology.</p> </div> </div> <h3>PATHWAY</h3><h4>Pathways for Students</h4> <div> <div> <p>Participants are provided with advice on employment and training options throughout the delivery of the program.</p> </div> </div> <h4>Employment Pathway</h4> <div> <div> <p>Job roles and titles vary across different industry sectors. Possible job titles relevant to this qualification include:</p> <ul> <li>Automotive Electrical Technician</li> <li>Automotive Electrician</li> <li>Automotive Electrical Workshop Technical Service Advisor</li> <li>Automotive Electrical Workshop Manager/Service Manager</li> </ul> <p><a href="https://training.gov.au/Training/Details/AUR30320" rel="noopener noreferrer" target="_blank"><span>https://training.gov.au/Training/Details/AUR30320</span></a><br/> <a href="https://www.myskills.gov.au/courses/details?Code=AUR30320" rel="noopener noreferrer" target="_blank"><span>https://www.myskills.gov.au/courses/details?Code=AUR30320</span></a></p> </div> </div> </div>',
    total_course_duration = '12 Months',
    offshore_tuition_fee = 13500,
    enrolment_fee = 350,
    materials_fee = 1200,
    entry_requirements = '<h4>Entry Requirements</h4><div><h3>ENTRY REQUIREMENTS</h3> <div> <div> <p><span>Aspen College has the following entry requirements:</span></p> <p><span>You must:</span></p> <ul> <li><span>be at least 18 years of age </span></li> <li><span>have an IELTS* score of 5.5 (test results must be no more than 2 years old). English language competence can also be demonstrated through documented evidence of any of the following:</span> <ul> <li><span>educated for 5 years in an English-speaking country; or</span></li> <li><span>completed at least 6 months of a Certificate IV level course in an Australian RTO; or</span></li> <li><span>successful completion of an English Placement Test.</span></li> </ul> </li> </ul> <p><em>Note that other English language tests such as PTE and TOEFL can be accepted. You are required to provide your results so that we can confirm they are equivalent to IELTS 5.5.</em></p> </div> </div> <h3>RECOGNITION OF PRIOR LEARNING (RPL) AND CREDIT TRANSFER (CT)</h3> <div> <div> <p>RPL is a form of assessment that acknowledges skills and knowledge gained through:</p> <ul> <li>Formal/Informal training conducted by industry or education</li> <li>Work experience</li> <li>Life experience</li> </ul> <p>The main principle of RPL focuses on the outcomes rather than when or where the learning occurred. Evidence of competency is collected by the applicant and submitted to the nominated assessor and assessment is made based on the required industry standard within the relevant training package unit of competency.</p> <p>Aspen College is committed to providing up to date and relevant RPL information to all students during enrolment and whilst enrolled. Aspen College staff will provide support and guidance regarding RPL enquiries. All applicants for Recognition of Prior Learning (RPL) will be provided with a copy of the relevant unit of competency and evidence requirements for the units being applied for.</p> <p>Applicants who are able to provide satisfactory evidence that they have achieved the required unit of competency or competencies may progress through the course with an exemption for the RPL units.</p> </div> </div> <h4>Recognition of Prior Learning</h4> <div> <div> <p>Recognition of Prior Learning Recognition of prior learning (RPL) is an assessment process that involves assessment of an individual’s relevant prior learning (including formal, informal and non-formal learning) to determine the credit outcomes of an individual application for credit.</p> <p>(Source: <a href="https://www.aqf.edu.au/sites/aqf/files/rpl-explanation.pdf" rel="noopener noreferrer" target="_blank">https://www.aqf.edu.au/sites/aqf/files/rpl-explanation.pdf</a> )</p> </div> </div> <h4>Credit Transfer</h4> <div> <div> <p>Credit Transfer Credit transfer is a process that provides students with agreed and consistent credit outcomes for components of a qualification based on identified equivalence in content and learning outcomes between matched qualifications.</p> <p>(Source: <a href="https://www.aqf.edu.au/sites/aqf/files/credit-transfer-explanation.pdf" rel="noopener noreferrer" target="_blank">https://www.aqf.edu.au/sites/aqf/files/credit-transfer-explanation.pdf</a>)</p> </div> </div> </div>',
    apply_form = 'https://www.aspencollege.edu.au/courses/aur30320-certificate-iii-in-automotive-electrical-technology/',
    updated_at = NOW()
WHERE cricos_course_code = '111281G';
UPDATE courses SET
    course_description = '<h4>Course Intro</h4><div> <div> <p>This is a qualification suitable for individuals who want to undertake leadership and management role in the Automotive industry</p> </div> </div><h4>Course Outline</h4><div> <div> <div> <table> <tbody> <tr> <th colspan="2">Core Unit</th> </tr> <tr> <td>AURAEA004</td> <td>Manage environmental and sustainability best practice in an automotive workplace</td> </tr> <tr> <td>AURAMA005</td> <td>Manage complex customer issues in an automotive workplace</td> </tr> <tr> <td>AURAMA006</td> <td>Contribute to planning and implementing business improvement in an automotive workplace</td> </tr> <tr> <td>BSBFIM501</td> <td>Manage budgets and financial plans</td> </tr> <tr> <td>BSBMGT502</td> <td>Manage people performance</td> </tr> <tr> <td>BSBWHS501</td> <td>Ensure a safe workplace</td> </tr> </tbody> </table> </div> </div> <div> <div> <table> <tbody> <tr> <th colspan="2">Elective Unit</th> </tr> <tr> <td>BSBHRM405</td> <td>Support the recruitment, selection and induction of staff</td> </tr> <tr> <td>BSBWOR501</td> <td>Manage personal work priorities and professional development</td> </tr> <tr> <td>BSBLED401</td> <td>Develop teams and individuals</td> </tr> <tr> <td>BSBCUS501</td> <td>Manage quality customer service</td> </tr> <tr> <td>BSBMGT517</td> <td>Manage operational plans</td> </tr> <tr> <td>BSBFIA401</td> <td>Prepare financial reports</td> </tr> </tbody> </table> </div> </div> </div><h4>Learning Outcomes &amp; Career Pathways</h4><div><h3>QUALIFICATION</h3> <div> <div> <p>On successful completion of this course the student would be awarded AUR50116 Diploma of Automotive Management which is nationally recognised qualification. This could help student gain entry into relevant career paths. Students who do not complete all units and/or works placement may be eligible for a Statement of Attainment in partial completion of a AUR50116 Diploma of Automotive Management.</p> </div> </div> <h3>PATHWAY</h3><h4>Pathways for Students</h4> <div> <div> <p><span lang="EN-AU">Participants are provided with advice on employment and training options throughout the delivery of the program.<o:p></o:p></span></p> </div> </div> <h4>Employment Pathway</h4> <div> <div> <p>Job roles and titles vary across different industry sectors. Possible job titles relevant to this qualification include:</p> <ul> <li><span>Dealership Manager</span></li> <li><span>Automotive Workshop Manager</span></li> <li><span>Automotive Warehouse Manager</span></li> <li><span>Automotive parts manager</span></li> <li><span>Business Manager</span></li> </ul> <p><a href="https://training.gov.au/Training/Details/AUR50116" rel="noopener noreferrer" target="_blank"><span>https://training.gov.au/Training/Details/AUR50116</span></a></p> <p><span><a href="https://www.myskills.gov.au/courses/details?Code=AUR50116" rel="noopener noreferrer" target="_blank">https://www.myskills.gov.au/courses/details?Code=AUR50116</a></span></p> </div> </div> </div>',
    total_course_duration = '26 weeks',
    offshore_tuition_fee = 10000,
    enrolment_fee = 350,
    materials_fee = 500,
    entry_requirements = '<h4>Entry Requirements</h4><div><h2>ENTRY REQUIREMENTS</h2> <div> <div> <p><span>Entry into this program requires International Students to fulfil requirements as listed below:</span></p> <ul> <li><span>Must be 18 years of age or over.</span></li> <li><span>Completed year 12 (HSC or equivalent).</span></li> <li><span>Minimum 5.5 IELTS score or equivalent.</span></li> <li><span>International students are required to hold Overseas Student Health Insurance cover for the duration of the course</span></li> <li><span>Students will be required to bring their laptop device (BYOD – bring your own device) and Aspen College will provide access to internet</span></li> <li><span>Those undertaking the Diploma of Automotive Management must have completed an automotive Certificate IV qualification in one of the following disciplines or be able to demonstrate equivalent competency.</span> <ul> <li><span>AUR40216 Certificate IV in Automotive Mechanical Diagnosis</span></li> <li><span>AUR40816 Certificate IV in Automotive Mechanical Overhauling.</span></li> </ul> </li> </ul> </div> </div> <h3>RECOGNITION OF PRIOR LEARNING (RPL) AND CREDIT TRANSFER (CT)</h3> <div> <div> <p>RPL is a form of assessment that acknowledges skills and knowledge gained through:</p> <ul> <li>Formal/Informal training conducted by industry or education</li> <li>Work experience</li> <li>Life experience</li> </ul> <p>The main principle of RPL focuses on the outcomes rather than when or where the learning occurred. Evidence of competency is collected by the applicant and submitted to the nominated assessor and assessment is made based on the required industry standard within the relevant training package unit of competency.</p> <p>Aspen College is committed to providing up to date and relevant RPL information to all students during enrolment and whilst enrolled. Aspen College staff will provide support and guidance regarding RPL enquiries. All applicants for Recognition of Prior Learning (RPL) will be provided with a copy of the relevant unit of competency and evidence requirements for the units being applied for.</p> <p>Applicants who are able to provide satisfactory evidence that they have achieved the required unit of competency or competencies may progress through the course with an exemption for the RPL units.</p> </div> </div> <h4>Recognition of Prior Learning</h4> <div> <div> <p>Recognition of Prior Learning Recognition of prior learning (RPL) is an assessment process that involves assessment of an individual’s relevant prior learning (including formal, informal and non-formal learning) to determine the credit outcomes of an individual application for credit.</p> </div> </div> <h4>Credit Transfer</h4> <div> <div> <p>Credit Transfer Credit transfer is a process that provides students with agreed and consistent credit outcomes for components of a qualification based on identified equivalence in content and learning outcomes between matched qualifications.</p> </div> </div> </div>',
