UPDATE courses SET
    course_description = '<h4>Course Outline</h4><div> <div> <div> <table> <tbody> <tr> <th colspan="2">Core Unit</th> </tr> <tr> <td>BSBCRT611</td> <td>Apply critical thinking for complex problem solving</td> </tr> <tr> <td>BSBOPS601</td> <td>Develop and implement business plans</td> </tr> <tr> <td>BSBSUS601</td> <td>Lead corporate social responsibility</td> </tr> <tr> <td>BSBTEC601</td> <td>Review organisational digital strategy</td> </tr> <tr> <td>BSBFIN601</td> <td>Manage organisational finances</td> </tr> </tbody> </table> </div> </div> <div> <div> <table> <tbody> <tr> <th colspan="2">Elective Unit</th> </tr> <tr> <td>BSBSTR602</td> <td>Develop organisational strategies</td> </tr> <tr> <td>BSBCMM511</td> <td>Communicate with influence</td> </tr> <tr> <td>BSBOPS505</td> <td>Manage organisational customer service</td> </tr> <tr> <td>BSBHRM614</td> <td>Contribute to strategic workforce planning</td> </tr> <tr> <td>BSBLDR601</td> <td>Lead and manage organisational change</td> </tr> </tbody> </table> </div> </div> </div><h4>Learning Outcomes &amp; Career Pathways</h4><div><h3>QUALIFICATION</h3> <div> <div> <p>On successful completion of this course the student would be awarded BSB60215 Advanced Diploma of Business which is nationally recognised qualification. This could help student gain entry into career paths or higher education in Business stream. Students who do not complete all units may be eligible for a Statement of Attainment in partial completion of a BSB60215 Advanced Diploma of Business.</p> <p><a href="http://training.gov.au/Training/Details/BSB60215" rel="noopener noreferrer" target="_blank">http://training.gov.au/Training/Details/BSB60215</a><br/> <a href="https://www.myskills.gov.au/courses/details?Code=BSB60215" rel="noopener noreferrer" target="_blank">https://www.myskills.gov.au/courses/details?Code=BSB60215</a></p> </div> </div> <h3>PATHWAY</h3><h4>Pathways for Students</h4> <div> <div> <p>Participants are provided with advice on employment and training options throughout the delivery of the program.<br/> Learners exiting this qualification may choose to progress with further studies by undertaking one or more of the following qualifications:</p> <ul> <li>A range of other qualifications at Advanced Diploma level</li> <li>A range of other qualification at Graduate Diploma of Strategic Leadership</li> <li>Possible entry to university degree subject to acceptance of student by the university</li> </ul> </div> </div> <h4>Employment Pathway</h4> <div> <div> <p>Job roles and titles vary across different industry sectors. Possible job titles relevant to this qualification include:</p> <ul> <li>Business Analyst</li> <li>Quarry Business Manager</li> <li>Administrator</li> <li>Senior Executive</li> <li>Business Development Director</li> </ul> </div> </div> </div>',
