UPDATE courses SET
    course_description = '<h4>Course Intro</h4><div> <div> <p>This qualification reflects the role of individuals who perform a broad range of tasks on a variety of light vehicles in the automotive retail, service and repair industry.</p> </div> </div><h4>Course Outline</h4><div> <div> <div> <table> <tbody> <tr> <th colspan="2">Core Unit</th> </tr> <tr> <td>AURAEA002</td> <td>Follow environmental and sustainability best practice in an automotive workplace</td> </tr> <tr> <td>AURASA102</td> <td>Follow safe working practices in an automotive workplace</td> </tr> <tr> <td>AURTTK102</td> <td>Use and maintain tools and equipment in an automotive workplace</td> </tr> <tr> <td>AURETR112</td> <td>Test and repair basic electrical circuits</td> </tr> <tr> <td>AURETR123</td> <td>Diagnose and repair spark ignition engine management systems</td> </tr> <tr> <td>AURETR125</td> <td>Test, charge and replace batteries and jump-start vehicles</td> </tr> <tr> <td>AURETR129</td> <td>Diagnose and repair charging systems</td> </tr> <tr> <td>AURETR130</td> <td>Diagnose and repair starting systems</td> </tr> <tr> <td>AURETR131</td> <td>Diagnose and repair ignition systems</td> </tr> <tr> <td>AURLTB103</td> <td>Diagnose and repair light vehicle hydraulic braking systems</td> </tr> <tr> <td>AURLTZ101</td> <td>Diagnose and repair light vehicle emission control systems</td> </tr> <tr> <td>AURLTD104</td> <td>Diagnose and repair light vehicle steering system</td> </tr> <tr> <td>AURLTE102</td> <td>Diagnose and repair light vehicle engines</td> </tr> <tr> <td>AURLTD105</td> <td>Diagnose and repair light vehicle suspension systems</td> </tr> <tr> <td>AURTTF101</td> <td>Inspect and service petrol fuel systems</td> </tr> <tr> <td>AURTTA104</td> <td>Carry out servicing operations</td> </tr> <tr> <td>AURTTE104</td> <td>Inspect and service engines</td> </tr> <tr> <td>AURTTB101</td> <td>Inspect and service braking systems</td> </tr> <tr> <td>AURTTC103</td> <td>Diagnose and repair cooling systems</td> </tr> <tr> <td>AURTTA118</td> <td>Develop and carry out diagnostic test strategies</td> </tr> <tr> <th colspan="2">Elective Unit</th> </tr> <tr> <td>AURTTK001</td> <td>Use and maintain measuring equipment in an automotive workplace</td> </tr> <tr> <td>AURAFA103</td> <td>Communicate effectively in an automotive workplace</td> </tr> <tr> <td>AURLTX103</td> <td>Diagnose and repair light vehicle clutch systems</td> </tr> <tr> <td>AURETR143</td> <td>Diagnose and repair electronic body management systems</td> </tr> <tr> <td><span>AURETR128</span></td> <td>Diagnose and repair instruments and warning systems</td> </tr> <tr> <td>AURLTJ102</td> <td>Remove, inspect, repair and refit light vehicle tyres and tubes</td> </tr> <tr> <td>AURLTJ113</td> <td>Remove, inspect and refit light vehicle wheel and tyre assemblies</td> </tr> <tr> <td>AURTTJ011</td> <td>Balance wheels and tyres</td> </tr> <tr> <td><span>AURETR132</span></td> <td>Diagnose and repair automotive electrical systems</td> </tr> <tr> <td>AURLTX101</td> <td>Diagnose and repair light vehicle manual transmissions</td> </tr> <tr> <td>AURLTQ102</td> <td>Diagnose and repair light vehicle drive shafts</td> </tr> <tr> <td>AURLTQ101</td> <td>Diagnose and repair light vehicle final drive assemblies</td> </tr> <tr> <td>AURTTA105</td> <td>Select and use bearings, seals, gaskets, sealants and adhesives</td> </tr> <tr> <td>AURTTF102</td> <td>Inspect and service diesel fuel injection systems</td> </tr> <tr> <td><span>AURTTZ102</span></td> <td>Diagnose and repair exhaust systems</td> </tr> <tr> <td>AURLTX102</td> <td>Diagnose and repair light vehicle automatic transmission</td> </tr> </tbody> </table> </div> </div> </div><h4>Learning Outcomes &amp; Career Pathways</h4><div><h3>QUALIFICATION</h3> <div> <div> <p>On successful completion of this course the student would be awarded AUR30616 Certificate III in Light Vehicle Mechanical Technology which is nationally recognised qualification. This could help student gain entry into career paths or higher education in Automotive stream. Students who do not complete all units and/or works placement may be eligible for a Statement of Attainment in partial completion of a AUR30616 Certificate III in Light Vehicle Mechanical Technology.</p> </div> </div> <h3>PATHWAY</h3><h4>Pathways for Students</h4> <div> <div> <p>Participants are provided with advice on employment and training options throughout the delivery of the program.<br/> After achieving the AUR30616 Certificate III in in Light Vehicle Mechanical Technology, candidates may choose to undertake AUR40216 Certificate IV in Automotive Mechanical Diagnosis or other relevant qualifications.</p> </div> </div> <h4>Employment Pathway</h4> <div> <div> <p>Job roles and titles vary across different industry sectors. Possible job titles relevant to this qualification include:</p> <ul> <li>Light Vehicle Mechanical Technician</li> <li>Automotive Light Vehicle Mechanical Repair Technician</li> <li>Motor Mechanic (General)</li> </ul> <p><a href="http://training.gov.au/Training/Details/AUR30616" rel="noopener noreferrer" target="_blank">http://training.gov.au/Training/Details/AUR30616</a><br/> <a href="https://www.myskills.gov.au/courses/details?Code=AUR30616" rel="noopener noreferrer" target="_blank">https://www.myskills.gov.au/courses/details?Code=AUR30616</a></p> </div> </div> </div>',
    total_course_duration = '12 Months',
