    course_description = '<h4>Course Intro</h4><div> <div> <p>This qualification reflects the role of individuals who perform advanced diagnostic tasks in the automotive retail, service and repair industry.</p> </div> </div><h4>Course Outline</h4><div> <div> <div> <table> <tbody> <tr> <th colspan="2">Core Unit</th> </tr> <tr> <td>AURTTA021</td> <td>Diagnose complex system faults</td> </tr> <tr> <th colspan="2">Elective Unit</th> </tr> <tr> <td>AURETR037</td> <td>Diagnose complex faults in light vehicle safety systems</td> </tr> <tr> <td>AURLTB104</td> <td>Diagnose complex faults in light vehicle braking systems</td> </tr> <tr> <td>AURLTD109</td> <td>Diagnose complex faults in light vehicle steering and suspension systems</td> </tr> <tr> <td>AURLTE104</td> <td>Diagnose complex faults in light vehicle petrol engines</td> </tr> <tr> <td>AURLTE105</td> <td>Diagnose complex faults in light vehicle diesel engines systems</td> </tr> <tr> <td>AURLTX104</td> <td>Diagnose complex faults in light vehicle automatic transmission and driveline systems</td> </tr> <tr> <td>AURTTA125</td> <td>Diagnose complex faults in vehicle integrated stability control systems</td> </tr> <tr> <td>AURTTR101</td> <td>Diagnose complex faults in engine management systems</td> </tr> <tr> <td>AURAEA004</td> <td>Manage environmental and sustainability best practice in an automotive workplace</td> </tr> </tbody> </table> </div> </div> </div><h4>Learning Outcomes &amp; Career Pathways</h4><div><h3>QUALIFICATION</h3> <div> <div> <p>On successful completion of this course the student would be awarded AUR40216 Certificate IV in Automotive Mechanical Diagnosis which is nationally recognised qualification. This could help student gain entry into career paths<br/> or higher education in Automotive stream. Students who do not complete all units and/or works placement may be eligible for a Statement of Attainment in partial completion of a AUR40216 Certificate IV in Automotive Mechanical Diagnosis.</p> </div> </div> <h3>PATHWAY</h3><h4>Pathways for Students</h4> <div> <div> <p>Participants are provided with advice on employment and training options throughout the delivery of the program.<br/> After achieving the AUR40216 Certificate IV in Automotive Mechanical Diagnosis, candidates may choose to undertake AUR50216 Diploma of Automotive Technology or other relevant qualifications.</p> </div> </div> <h4>Employment Pathway</h4> <div> <div> <p>Job roles and titles vary across different industry sectors. Possible job titles relevant to this qualification include:</p> <ul> <li>Automotive Heavy Vehicle Master Technician</li> <li>Automotive Master Technician</li> <li>Automotive Mechanical Overhaul Technician</li> <li>Performance Vehicle Technician</li> </ul> <p><a href="http://training.gov.au/Training/Details/AUR40216" rel="noopener noreferrer" target="_blank">http://training.gov.au/Training/Details/AUR40216</a><br/> <a href="https://www.myskills.gov.au/courses/details?Code=AUR40216" rel="noopener noreferrer" target="_blank">https://www.myskills.gov.au/courses/details?Code=AUR40216</a></p> </div> </div> </div>',
