UPDATE courses SET
    course_description = '<h4>Course Outline</h4><div> <div> <div> <table> <tbody> <tr> <th colspan="2">Core Unit</th> </tr> <tr> <td>CPCCCA2002*</td> <td>Use carpentry tools and equipment</td> </tr> <tr> <td>CPCCCA2011*</td> <td>Handle carpentry materials</td> </tr> <tr> <td>CPCCCA3001*</td> <td>Carry out general demolition of minor building structures</td> </tr> <tr> <td>CPCCCA3002*</td> <td>Carry out setting out</td> </tr> <tr> <td>CPCCCA3003*</td> <td>Install flooring systems</td> </tr> <tr> <td>CPCCCA3004*</td> <td>Construct and erect wall frames</td> </tr> <tr> <td>CPCCCA3005*</td> <td>Construct ceiling frames</td> </tr> <tr> <td>CPCCCA3006*</td> <td>Erect roof trusses</td> </tr> <tr> <td>CPCCCA3007*</td> <td>Construct pitched roofs</td> </tr> <tr> <td>CPCCCA3008*</td> <td>Construct eaves</td> </tr> <tr> <td>CPCCCA3010*</td> <td>Install windows and doors</td> </tr> <tr> <td>CPCCCA3016*</td> <td>Construct, assemble and install timber external stairs</td> </tr> <tr> <td>CPCCCA3017*</td> <td>Install exterior cladding</td> </tr> <tr> <td>CPCCCA3024*</td> <td>Install lining, panelling and moulding</td> </tr> <tr> <td>CPCCCA3025*</td> <td>Read and interpret plans, specifications, and drawings for carpentry work</td> </tr> <tr> <td>CPCCCA3028*</td> <td>Erect and dismantle formwork for footings and slabs on ground</td> </tr> <tr> <td>CPCCCM2006</td> <td>Apply basic levelling procedures</td> </tr> <tr> <td>CPCCCM2008*</td> <td>Erect and dismantle restricted height scaffolding</td> </tr> <tr> <td>CPCCCO2013*</td> <td>Carry out concreting to simple forms</td> </tr> <tr> <td>CPCCOM1012</td> <td>Work effectively and sustainably in the construction industry</td> </tr> <tr> <td>CPCCOM1014</td> <td>Conduct workplace communication</td> </tr> <tr> <td>CPCCOM1015</td> <td>Carry out measurements and calculations</td> </tr> <tr> <td>CPCCOM3001</td> <td>Perform construction calculations to determine carpentry material requirements</td> </tr> <tr> <td>CPCCOM3006</td> <td>Carry out levelling operations</td> </tr> <tr> <td>CPCCWHS2001</td> <td>Apply WHS requirements, policies and procedures in the construction industry</td> </tr> <tr> <td>CPCWHS3001</td> <td>Identify construction work hazards and select risk control strategies</td> </tr> <tr> <td>CPCCCM2012*</td> <td>Work safely at heights</td> </tr> </tbody> </table> </div> </div> <div> <div> <table> <tbody> <tr> <th colspan="2">Elective Unit</th> </tr> <tr> <td>CPCCCA3012*</td> <td>Frame and fit wet area fixtures</td> </tr> <tr> <td>CPCCCA3014*</td> <td>Construct and install bulkheads</td> </tr> <tr> <td>CPCCCM2002*</td> <td>Carry out hand excavation</td> </tr> <tr> <td>CPCCCA3027*</td> <td>Set up, operate and maintain indirect action powder-actuated power tools</td> </tr> <tr> <td>CPCCSF2004*</td> <td>Place and fix reinforcement materials</td> </tr> <tr> <td>CPCCCM3005</td> <td>Calculate costs of construction work</td> </tr> <tr> <td>CPCCOM1013</td> <td>Plan and organise work</td> </tr> </tbody> </table> </div> </div> </div><h4>Learning Outcomes &amp; Career Pathways</h4><div><h3>QUALIFICATION</h3> <div> <div> <p>On successful completion of this course the student would be awarded CPC30220 Certificate III in Carpentry which is nationally recognised qualification. This could help student gain entry into career paths or higher education into a range of building and construction qualifications. Students who do not complete all units and/or works placement may be eligible for a Statement of Attainment in partial completion of a CPC30220 Certificate III in Carpentry.</p> </div> </div> <h3>PATHWAY</h3><h4>Pathways for Students</h4> <div> <div> <p>Participants are provided with advice on employment and training options throughout the delivery of the program.</p> <p>After achieving the CPC30220 Certificate III in Carpentry, candidates may choose to undertake Certificate IV in Building and Construction (Building) and higher studies.</p> </div> </div> <h4>Employment Pathway</h4> <div> <div> <p>Job roles and titles vary across different industry sectors. Possible job titles relevant to this qualification include:</p> <ul> <li>Carpenter – Commercial</li> <li>Carpenter – Formwork</li> <li>Carpenter – Residential</li> </ul> <p><a href="https://training.gov.au/Training/Details/CPC30220" rel="noopener noreferrer" target="_blank">https://training.gov.au/Training/Details/CPC30220</a></p> <p><a href="https://www.myskills.gov.au/courses/details?Code=CPC30220" rel="noopener noreferrer" target="_blank">https://www.myskills.gov.au/courses/details?Code=CPC30220</a></p> </div> </div> </div>',
