UPDATE courses SET
    course_description = '<h4>Course Intro</h4><div> <div> <p>This program is designed for those seeking to build valuable management skills in the construction industry. Students will be learning specialist skills that are necessary for working at a senior management position within building and construction firms. Students will gain the professional skills and knowledge required for the operational and strategic planning and management of building projects. This will include financial management, team<br/> performance contractual obligations and quality systems. The latest release of the qualification and packaging rules can be found at the following link:<a href="https://training.gov.au/training/details/cpc50320" rel="noopener noreferrer" target="_blank"> https://training.gov.au/training/details/cpc50320</a></p> </div> </div><h4>Course Outline</h4><div> <div> <div> <table> <tbody> <tr> <th colspan="2">Core Unit</th> </tr> <tr> <td>BSBWHS513</td> <td>Lead WHS risk management</td> </tr> <tr> <td>CPCCBC4001</td> <td>Apply building codes and standards to the construction<br/> process for Class 1 and 10 Buildings</td> </tr> <tr> <td>CPCCBC4053</td> <td>Apply building codes and standards to the construction<br/> process for Class 2 to 9, Type C Buildings</td> </tr> <tr> <td>CPCCBC5002</td> <td>Monitor costing systems on complex building and<br/> construction projects</td> </tr> <tr> <td>CPCCBC5005</td> <td>Select and manage building and construction contractors</td> </tr> <tr> <td>CPCCBC5007</td> <td>Administer the legal obligations of a building or construction<br/> contractor</td> </tr> <tr> <td>CPCCBC5019</td> <td>Manage building and construction business finances</td> </tr> <tr> <td>BSBPMG536</td> <td>Manage project risk</td> </tr> </tbody> </table> </div> </div> <div> <div> <table> <tbody> <tr> <th colspan="2">Elective Unit</th> </tr> <tr> <td>BSBHRM415</td> <td>Coordinate recruitment and onboarding</td> </tr> <tr> <td>BSBOPS502</td> <td>Manage business operational plans</td> </tr> <tr> <td>BSBOPS505</td> <td>Manage organisational customer service</td> </tr> <tr> <td>BSBPEF502</td> <td>Develop and use emotional intelligence</td> </tr> <tr> <td>BSBPMG532</td> <td>Manage project quality</td> </tr> <tr> <td>CPCCBC4004</td> <td>Identify and produce estimated costs for building and<br/> construction projects</td> </tr> <tr> <td>CPCCBC5011</td> <td>Manage environmental management practices and<br/> processes in building and construction</td> </tr> </tbody> </table> </div> </div> </div>',
