UPDATE courses SET
    course_description = '<h4>Course Outline</h4><div> <div> <div> <table> <tbody> <tr> <th colspan="2">Core Unit</th> </tr> <tr> <td>BSBPMG632</td> <td>Manage program risk</td> </tr> <tr> <td>BSBTWK502</td> <td>Manage team effectiveness</td> </tr> <tr> <td>BSBWHS616</td> <td>Apply safe design principles to control WHS risks</td> </tr> <tr> <td>RIICWD601E</td> <td>Manage civil works design processes</td> </tr> <tr> <td>RIIQUA601E</td> <td>Establish and maintain a quality system</td> </tr> </tbody> </table> </div> </div> <div> <div> <table> <tbody> <tr> <th colspan="2">Elective Unit</th> </tr> <tr> <td>BSBPMG531</td> <td>Manage project time</td> </tr> <tr> <td>RIICWD526E</td> <td>Prepare detailed traffic analysis</td> </tr> <tr> <td>RIILAT402E</td> <td>Provide leadership in the supervision of diverse work teams</td> </tr> <tr> <td><span>BSBSTR601</span></td> <td><span>Manage Innovation and continuous improvement</span></td> </tr> <tr> <td>BSBOPS601</td> <td>Develop and implement business plans</td> </tr> <tr> <td>BSBPMG530</td> <td>Manage project scope</td> </tr> <tr> <td><span>RIICWD512E</span></td> <td><span>Prepare detailed design of motorways and interchanges</span></td> </tr> </tbody> </table> </div> </div> </div><h4>Learning Outcomes &amp; Career Pathways</h4><div><h3>QUALIFICATION</h3> <div> <div> <p>On successful completion of this course the student would be awarded RII60520 Advanced Diploma Of Civil Construction Design which is nationally recognised qualification. After successfully completing the Advanced Diploma of Civil Construction Design, students may apply for the: Bachelor of Engineering (Civil). Students who do not complete all units and/or works placement may be eligible for a Statement of Attainment in partial completion of a RII60520 Advanced Diploma Of Civil Construction Design.</p> </div> </div> <h3>PATHWAY</h3><h4>Pathways for Students</h4> <div> <div> <p>Participants are provided with advice on employment and training options throughout the delivery of the program. After achieving the RII60520 Advanced Diploma Of Civil Construction Design, candidates may choose to undertake Bachelor of Engineering (Civil).</p> </div> </div> <h4>Employment Pathway</h4> <div> <div> <p>Job roles and titles vary across different industry sectors. Possible job titles relevant to this qualification include:</p> <ul> <li>Civil Construction Supervisor</li> <li>Civil Design Draftsperson</li> <li>Senior Civil Works Designer</li> </ul> <p><a href="https://training.gov.au/Training/Details/RII60520" rel="noopener noreferrer" target="_blank">https://training.gov.au/Training/Details/RII60520</a></p> <p><a href="https://www.myskills.gov.au/courses/details?Code=RII60520" rel="noopener noreferrer" target="_blank">https://www.myskills.gov.au/courses/details?Code=RII60520</a></p> </div> </div> </div>',
